export type IllustrationName = keyof typeof ILLUSTRATION;

/** SVG je lokálny, dôveryhodný statický návrhový podklad — nikdy nie obsah z databázy. */
export function Illustration({ name, className = "illustration" }: { name: IllustrationName; className?: string }) {
  return <span className={className} dangerouslySetInnerHTML={{ __html: ILLUSTRATION[name] }} />;
}

/** Pre návrhové fragmenty, ktoré samy obsahujú blokový element (aktuálne handRule). */
export function BlockIllustration({ name, className = "illustration" }: { name: IllustrationName; className?: string }) {
  return <div className={className} dangerouslySetInnerHTML={{ __html: ILLUSTRATION[name] }} />;
}
